              text: 'TRIANGLE (3 sides): Sum of angles = 180°\n  Equilateral: all sides equal, all angles 60°\n  Isosceles: two sides equal, two angles equal\n  Scalene: no sides equal, no angles equal\n\nQUADRILATERALS (4 sides): Sum of angles = 360°\n  Square: 4 equal sides, 4 right angles\n  Rectangle: opposite sides equal, 4 right angles\n  Rhombus: 4 equal sides, opposite angles equal\n  Parallelogram: opposite sides equal and parallel\n  Trapezium: exactly one pair of parallel sides\n\nREGULAR POLYGON: all sides equal AND all angles equal.',
