              text: 'SURVEY QUESTION: "What is your favourite sport?"\n\nResults (class of 28 students):\nCricket:   |||| |||| = 9\nFootball:  |||| |||| || = 12\nSwimming:  |||  = 3\nNetball:   |||| = 4\n\nTALLY TIPS:\n• Group in fives (four vertical, one diagonal) for easy counting.\n• Always double-check totals add to the total number surveyed.\n• 9 + 12 + 3 + 4 = 28 ✓',
