              text: 'FEATURES OF A GOOD BAR GRAPH:\n1. TITLE: "Favourite Sports of Year 5 Class"\n2. X-AXIS (horizontal): category labels (Cricket, Football, Swimming, Netball)\n3. Y-AXIS (vertical): frequency (number of students), starting at 0\n4. SCALE: count by 2s (0, 2, 4, 6, 8, 10, 12) — gives enough detail\n5. BARS: equal width, equal gaps between bars, correct height\n\nSCALE CHOICE RULE: Choose a scale so the tallest bar is about 3/4 of the graph height. If the max value is 12, scale of 2 works well.',
